-- 4. Seed Products
INSERT INTO products (
    id, brand_id, slug, title_fa, short_description_fa, full_description_fa, product_type, status, is_featured, published_at, created_at, updated_at
) VALUES
('33333333-0001-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 'moringa-leaf-powder-100g', 'پودر برگ مورینگا ۱۰۰ گرمی', 'پودر خالص و ارگانیک برگ درخت مورینگا، سرشار از آنتی‌اکسیدان، ویتامین و اسیدهای آمینه ضروری برای تقویت عمومی بدن.', 'پودر برگ مورینگا ۱۰۰ گرمی از برگ‌های تازه و دست‌چین شده درخت مورینگا اولیفرا تهیه گردیده است. این محصول با فرایند خشک‌سازی استاندارد، کلیه املاح معدنی و ویتامین‌های گیاهی خود را حفظ نموده است. بسته‌بندی زیپ‌کیپ آلومینیومی کیفیت و ماندگاری پودر را حفظ می‌کند.\n\nتذکر مهم: این محصول جایگزین توصیه پزشک یا درمان دارویی نیست و صرفاً مکمل غذایی ارگانیک می‌باشد.', 'simple', 'published', true, NOW(), NOW(), NOW()),
('33333333-0002-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 'moringa-leaf-powder-250g', 'پودر برگ مورینگا ۲۵۰ گرمی', 'بسته‌بندی اقتصادی پودر خالص برگ مورینگا ۲۵۰ گرمی مناسب برای مصرف مداوم خانوار.', 'پودر برگ مورینگا ۲۵۰ گرمی بسته‌بندی خانوادگی و باصرفه برای علاقه‌مندان به سبک زندگی سالم است. این محصول با داشتن بیش از ۹۲ ماده مغذی، ۴۶ نوع آنتی‌اکسیدان و ۱۸ اسید آمینه، مکمل غذایی فوق‌العاده‌ای است.\n\nتذکر مهم: این محصول جایگزین توصیه پزشک یا درمان دارویی نیست.', 'simple', 'published', true, NOW(), NOW(), NOW()),
('33333333-0003-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 'dried-moringa-leaves-50g', 'برگ خشک مورینگا ۵۰ گرمی', 'برگ‌های خشک کامل و سالم مورینگا مناسب جهت دم‌آوری دمنوش و اضافه کردن به غذا.', 'برگ خشک مورینگا ۵۰ گرمی به روش طبیعی سایه‌خشک آماده گردیده است. این محصول بافت سالم برگ را حفظ نموده و عطری ملایم و مطبوع دارد.', 'simple', 'published', false, NOW(), NOW(), NOW()),
('33333333-0004-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 'moringa-lemon-tea-20', 'دمنوش مورینگا و لیمو ۲۰ عددی', 'ترکیب باطراوت برگ مورینگا و لیموعمانی طبیعی در کیسه‌های تجدیدپذیر.', 'دمنوش ترکیب مورینگا و لیمو ۲۰ عددی، حس نشاط و شادابی را همراه با خواص طبیعی مورینگا به شما هدیه می‌دهد. این دمنوش فاقد کافئین بوده و گزینه‌ای عالی برای عصرانه است.', 'simple', 'published', true, NOW(), NOW(), NOW()),
('33333333-0005-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 'moringa-cinnamon-tea-20', 'دمنوش مورینگا و دارچین ۲۰ عددی', 'دمنوش گرم‌آفرین ترکیب برگ مورینگا و دارچین قلمی سیلان جهت ایجاد آرامش و صمیمیت.', 'دمنوش مورینگا و دارچین ۲۰ عددی با طبع گرم و مطبوع خود، انتخابی ایده‌آل برای روزهای سرد سال است.', 'simple', 'published', false, NOW(), NOW(), NOW()),
('33333333-0006-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 'moringa-capsules-60', 'کپسول مورینگا ۶۰ عددی', 'کپسول‌های گیاهی حاوی پودر خالص برگ مورینگا، روشی آسان و سریع برای مصرف روزانه.', 'کپسول مورینگا ۶۰ عددی گزینه‌ای عالی برای افرادی است که طعم پودر مورینگا را در نوشیدنی نمی‌پسندند. پوکه کپسول‌ها ۱۰۰٪ گیاهی سلولزی بوده و سریع هضم می‌شوند.', 'simple', 'published', true, NOW(), NOW(), NOW()),
('33333333-0007-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 'moringa-oil-30ml', 'روغن مورینگا ۳۰ میلی‌لیتری', 'روغن خالص دانه مورینگا استخراج شده به روش پرس سرد، مناسب برای مراقبت پوست و مو.', 'روغن مورینگا ۳۰ میلی‌لیتری از دانه‌های مرغوب درخت مورینگا اولیفرا با فناوری پرس سرد تهیه شده است. این روغن سبک جذب سریعی داشته و رطوبت پوست را حفظ می‌کند.', 'simple', 'published', true, NOW(), NOW(), NOW()),
('33333333-0008-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 'moringa-seeds-100g', 'دانه مورینگا ۱۰۰ گرمی', 'دانه‌های خام و تازه مورینگا اولیفرا مناسب برای کاشت و استخراج عصاره یا مصرف خانگی.', 'دانه مورینگا ۱۰۰ گرمی محصولی ارگانیک و طبیعی است. این دانه‌ها دارای قوه‌نامیه بالا بوده و برای علاقه‌مندان به کشت گیاهان دارویی بسیار مناسب است.', 'simple', 'published', false, NOW(), NOW(), NOW()),
('33333333-0009-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 'moringa-starter-pack', 'بسته آشنایی با مورینگا', 'پک ترکیبی شامل پودر برگ، دمنوش لیمو و روغن ۳۰ میل مورینگا جهت تجربه جامع از محصولات.', 'بسته آشنایی با مورینگا، انتخابی هوشمندانه برای کسانی است که می‌خواهند برای اولین بار تنوع محصولات مورینگا را تجربه نمایند. شامل ۱۰۰ گرم پودر برگ، دمنوش لیمو ۲۰ عددی و روغن ۳۰ میل.', 'simple', 'published', true, NOW(), NOW(), NOW()),
('33333333-0010-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 'moringa-gift-box', 'بسته هدیه مورینگا', 'جعبه کادویی شکیل چوبی شامل کامل‌ترین مجموعه محصولات مورینگا مناسب برای هدیه سلامتی.', 'بسته هدیه مورینگا در جعبه چوبی دست‌ساز نفیس قرار دارد. این بسته حاوی پودر برگ ۲۵۰ گرمی، دمنوش لیمو، کپسول ۶۰ عددی و روغن ۳۰ میل مورینگا می‌باشد.', 'simple', 'published', true, NOW(), NOW(), NOW())
ON CONFLICT (id) DO NOTHING;

