-- 10. Seed Articles
INSERT INTO articles (
    id, category_id, author_name_fa, slug, title_fa, summary_fa, content_fa, cover_image_url, status, version, disclaimers_fa, reading_time_minutes, seo_title, seo_description, published_at, created_at, updated_at
) VALUES
('77777777-0001-1111-1111-111111111111', '55555555-1111-1111-1111-111111111111', 'تیم تحریریه مورینگا ایران', 'what-is-moringa', 'مورینگا چیست؟ آشنایی ساده با این گیاه', 'معرفی جامع گیاه مورینگا اولیفرا، بخش‌های قابل مصرف، تاریخچه کشت و کاربردهای عمومی تغذیه‌ای آن در زندگی روزمره.', 'گیاه مورینگا اولیفرا یکی از شناخته‌شده‌ترین گیاهان بومی مناطق گرمسیری است...\n\nاین مطلب صرفاً برای آشنایی عمومی است و جایگزین توصیه پزشک یا متخصص تغذیه نیست.', '/images/demo/articles/what-is-moringa.jpg', 'published', 1, 'این مطلب صرفاً برای آشنایی عمومی است و جایگزین توصیه پزشک یا متخصص تغذیه نیست.', 4, 'مورینگا چیست؟ معرفی کامل گیاه مورینگا اولیفرا و خواص عمومی', 'معرفی جامع گیاه مورینگا اولیفرا، اجزای مختلف درخت مورینگا و نحوه استفاده عمومی از پودر و برگ خشک آن.', NOW() - INTERVAL '9 days', NOW() - INTERVAL '9 days', NOW()),
('77777777-0002-1111-1111-111111111111', '55555555-2222-1111-1111-111111111111', 'تیم تحریریه مورینگا ایران', 'moringa-powder-vs-dried-leaves', 'تفاوت پودر مورینگا و برگ خشک مورینگا', 'بررسی تفاوت‌های ظاهری، نحوه مصرف، شیوه نگهداری و انتخاب بین پودر خالص برگ و برگ خشک کامل مورینگا.', 'هنگام تصمیم‌گیری برای خرید فرآورده‌های برگ مورینگا، با دو فرم اصلی مواجه می‌شوید...\n\nاین مطلب صرفاً برای آشنایی عمومی است و جایگزین توصیه پزشک نیست.', '/images/demo/articles/moringa-powder-vs-dried-leaves.jpg', 'published', 1, 'این مطلب صرفاً برای آشنایی عمومی است و جایگزین توصیه پزشک یا متخصص تغذیه نیست.', 5, 'مقایسه پودر مورینگا با برگ خشک - تفاوت‌ها و راهنمای انتخاب', 'بررسی تفاوت‌های پودر برگ مورینگا و برگ خشک کامل، شیوه استفاده در دمنوش یا غذا و انتخاب بهترین نوع.', NOW() - INTERVAL '8 days', NOW() - INTERVAL '8 days', NOW()),
('77777777-0003-1111-1111-111111111111', '55555555-3333-1111-1111-111111111111', 'تیم تحریریه مورینگا ایران', 'how-to-store-moringa-powder', 'راهنمای نگهداری صحیح پودر مورینگا', 'نکات مهم کلیدی برای حفظ کیفیت، رنگ سبز طبیعی، عطر و طعم پودر مورینگا در برابر نور، رطوبت و اکسیژن.', 'پودر برگ مورینگا ماده‌ای حساس به عوامل محیطی مانند نور مستقیم، اکسیژن و رطوبت است...', '/images/demo/articles/how-to-store-moringa-powder.jpg', 'published', 1, 'این مطلب صرفاً برای آشنایی عمومی است و جایگزین توصیه پزشک یا متخصص تغذیه نیست.', 4, 'راهنمای نگهداری پودر مورینگا - اصول حفظ کیفیت و رنگ', 'روش‌های صحیح نگهداری پودر برگ مورینگا در خانه، محافظت در برابر نور و رطوبت و جلوگیری از کلوخه شدن.', NOW() - INTERVAL '7 days', NOW() - INTERVAL '7 days', NOW()),
